from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

# Set up.
hub = PrimeHub()
speed = 300
left = Motor(Port.A, Direction.COUNTERCLOCKWISE)
right = Motor(Port.E, Direction.CLOCKWISE)
drive_base = DriveBase(left, right, 56, 114)
lance = Motor(Port.D, Direction.COUNTERCLOCKWISE)
forklift = Motor(Port.C, Direction.CLOCKWISE)
tools = DriveBase(lance, forklift, 56, 114)

def my_67():
    drive_base.use_gyro(True)
    tools.use_gyro(True)
    speed67()
    lance.run_angle(500, -50)
    drive_base.straight(600)
    drive_base.turn(90)
    drive_base.straight(220)
    drive_base.turn(-90)
    # in front of tree
    # lance lowering
    lance.run_angle(500, -30)
    drive_base.straight(75)
    wait(250)
    # lance lifting
    lance.run_angle(500, 90)
    drive_base.straight(10)
    # getting vine to touch the map
    drive_base.straight(-120)
    drive_base.straight(128)
    # lift lifting
    forklift.run_angle(500, 1840)
    drive_base.straight(-30)
    lance.run_angle(500, -120)
    drive_base.straight(-75)
    drive_base.turn(90)
    drive_base.straight(-220)
    drive_base.turn(-72)
    lance.run_angle(500, 50)
    drive_base.straight(110)
    lance.run_angle(500, 25)
    wait(250)
    drive_base.turn(-45)
    drive_base.turn(60)
    drive_base.straight(-115)
    drive_base.turn(-37)
    lance.run_angle(500, -90)
    wait(250)
    drive_base.straight(58)
    lance.run_angle(100, 145)
    drive_base.straight(100)
    drive_base.turn(-180)
    drive_base.use_gyro(False)
    drive_base.settings(straight_speed=800)
    drive_base.straight(800)

def speed67():
    drive_base.settings(straight_speed=speed)


# The main program starts here.
# millimeter left to the most right solid black line
my_67()
